	{ id = 60, module = "tweaks",
		en = { "Bags: the clean-up button is back", "Forever's latest patch removed the bags' clean-up button, with mouse and keyboard and in gamepad mode. It's back, at the left of the bags' search box." },
		de = { "Taschen: Aufräumen-Knopf ist zurück", "Mit dem letzten Forever-Patch fehlte der Aufräumen-Knopf der Taschen, mit Maus und Tastatur wie im Gamepad-Modus. Er ist zurück, links neben dem Suchfeld der Taschen." } },
	{ id = 61, module = "beacon",
		en = { "Watch your friends' fights live", "A small live view of a friend's fight: them in the middle on the map, the mobs around them, their group and other players nearby, what they're casting. Click their dot on the world map to open it (again to close), pick them from the spyglass button on the minimap, or /lefthy stream watch <name>. On a cinematic flight one friend's fight opens by itself, and the top bar has a Watch button for each friend. Drag the window's corner to resize it. A tiny red dot by the minimap's calendar button shows when friends watch you; sharing can be switched off in the Beacon settings." },
		de = { "Kämpfe deiner Freunde live ansehen", "Eine kleine Live-Ansicht vom Kampf eines Freundes: er in der Mitte auf der Karte, die Mobs um ihn herum, seine Gruppe und andere Spieler in der Nähe, was er gerade wirkt. Klick seinen Punkt auf der Weltkarte an, um sie zu öffnen (nochmal zum Schließen), wähl ihn am Fernrohr-Button an der Minimap, oder /lefthy stream watch <name>. Auf einem Flug im Kinomodus öffnet sich der Kampf eines Freundes von selbst, und die obere Leiste hat für jeden Freund einen Zuschauen-Button. Zieh an der Ecke des Fensters, um die Größe zu ändern. Ein winziger roter Punkt am Kalender-Button der Minimap zeigt, wenn Freunde dir zuschauen; das Teilen lässt sich in den Beacon-Einstellungen abschalten." } },
	{ id = 62, module = "chronicle",
		en = { "Friends' news even when they're offline", "Battle.net only reaches friends who are online, so now your friends' LefthyTools pass each other's journals on: whoever is online brings you the news, days and numbers of those who aren't, and yours reach them the same way. Only to people who have that player as a Battle.net friend too. The Friends page lists who isn't online, when they last played and their latest news; a blue dot on the book says there's something new." },
		de = { "Neues von Freunden, auch wenn offline", "Battle.net erreicht nur Freunde, die online sind, deshalb geben die LefthyTools deiner Freunde ihre Tagebücher jetzt untereinander weiter: wer online ist, bringt dir die Neuigkeiten, Tage und Zahlen derer mit, die es nicht sind, und deine erreichen sie genauso. Nur an Leute, die diesen Spieler auch als Battle.net-Freund haben. Die Freunde-Seite zeigt, wer nicht online ist, wann er zuletzt gespielt hat und seine letzten Neuigkeiten; ein blauer Punkt am Buch sagt, dass es Neues gibt." } },
	{ id = 63, module = "chronicle",
		en = { "Compare: all friends in every graph", "A new Compare page: you and every friend in every graph, a line each: level, time played, XP, quests, kills, deaths, gold, distance, bosses and rares, time AFK and jumps over 7, 14 or 30 days. Plus this week's leaderboard with the Martin award, a hall of fame and records. Share posts a ranking in Lefthy chat." },
		de = { "Vergleich: alle Freunde in jedem Graphen", "Eine neue Vergleich-Seite: du und jeder Freund in jedem Graphen, eine Linie pro Person: Level, Spielzeit, Erfahrung, Quests, Kills, Tode, Gold, Strecke, Bosse und Rares, Zeit AFK und Sprünge über 7, 14 oder 30 Tage. Dazu die Bestenliste der Woche mit dem Martin-Preis, eine Ruhmeshalle und Rekorde. Teilen postet eine Rangliste im Lefthy-Chat." } },
	{ id = 64, module = "chronicle",
		en = { "While you were away, and a weekly recap", "A minute after you log in, a chat line per friend with what they did since you last played. And once a week, the first time you play, last week's leaderboard in chat." },
		de = { "Was du verpasst hast, und Wochenbilanz", "Eine Minute nach dem Einloggen eine Chatzeile pro Freund mit dem, was er seit deinem letzten Spielen gemacht hat. Und einmal pro Woche, beim ersten Spielen, die Bestenliste der letzten Woche im Chat." } },
	{ id = 65, module = "chronicle",
		en = { "AFK and jumps: for all your characters", "Some numbers are about the player, not the character: the Martin tracker (time AFK) and jumps now count all your characters together, in a new All your characters section of the statistics. The Compare page and the leaderboards go per person too: an alt's quests, kills and time count for its player." },
		de = { "AFK und Sprünge: alle Charaktere", "Manche Zahlen gehören zum Spieler, nicht zum Charakter: der Martin-Tracker (Zeit AFK) und die Sprünge zählen jetzt alle deine Charaktere zusammen, in einem neuen Abschnitt Alle deine Charaktere in der Statistik. Die Vergleich-Seite und die Bestenlisten gehen auch nach Person: Quests, Kills und Zeit eines Twinks zählen für seinen Spieler." } },
	{ id = 66, module = "mirage",
		en = { "Mirage: pause from the minimap", "A button on the minimap's edge while Mirage is on: click it to pause fading (the interface stays, the icon greys out), click again to fade when idle again. Right-click opens Mirage's settings. /mirage pause does the same." },
		de = { "Mirage: Pause an der Minimap", "Ein Button am Rand der Minimap, solange Mirage an ist: ein Klick pausiert das Ausblenden (das Interface bleibt, das Symbol wird grau), ein zweiter blendet wieder aus, wenn du nichts tust. Rechtsklick öffnet die Einstellungen von Mirage. /mirage pause macht dasselbe." } },
	{ id = 67, module = "tweaks",
		en = { "Flights: six friends, top and bottom", "On a cinematic flight three friends fit in the top bar and three more in the bottom one; the time left moves to its right end while they're there." },
		de = { "Flüge: sechs Freunde, oben und unten", "Auf einem Flug im Kinomodus passen drei Freunde in die obere Leiste und drei weitere in die untere; die Restzeit rückt dann an ihr rechtes Ende." } },
	{ id = 68, module = "tweaks",
		en = { "Flights: shared items can be hovered", "An item a friend shows you during a cinematic flight now has its tooltip when you hover it in the subtitles, and a click opens it (the film waits until you close it)." },
		de = { "Flüge: geteilte Items mit Tooltip", "Ein Item, das dir ein Freund während eines Flugs im Kinomodus zeigt, hat jetzt seinen Tooltip, wenn du in den Untertiteln mit der Maus darauf zeigst, und ein Klick öffnet es (der Film wartet, bis du es schließt)." } },
	{ id = 69, module = "tweaks",
		en = { "Combo gem: display's look, your place", "The combo point gem on your target's nameplate is now copied from the personal resource display's own, border and all, and smaller. Three new sliders set its size and where it sits; while you move them it shows on your target." },
		de = { "Combopunkt: Anzeige-Look, dein Platz", "Der Combopunkt an der Namensplakette deines Ziels ist jetzt eine Kopie des Punkts der persönlichen Ressourcenanzeige, mit Rand, und kleiner. Drei neue Regler bestimmen Größe und Position; während du sie bewegst, zeigt er sich an deinem Ziel." } },
	{ id = 70, module = "tweaks",
		en = { "Combo gem: place it without a mob", "Try it (Misc Tweaks, or /lefthy tweaks combopos) opens a small window with a nameplate: drag the combo point gem where you want it, the mouse wheel over it changes its size, the arrows nudge it. No mob needed, and the settings can be closed." },
		de = { "Combopunkt: platzieren ohne Mob", "Ausprobieren (Misc Tweaks, oder /lefthy tweaks combopos) öffnet ein kleines Fenster mit einer Namensplakette: zieh den Combopunkt dorthin, wo du ihn haben willst, das Mausrad darüber ändert seine Größe, die Pfeile verschieben ihn. Kein Mob nötig, und die Einstellungen können zu sein." } },
	{ id = 71, module = "chronicle",
		en = { "Friends' journals: more reliable", "A journal that arrived only in part is asked for again instead of counting as complete, everything is offered again every few minutes in case an offer got lost, and answering a friend's request no longer stutters the game. Players who are no longer your Battle.net friends drop out of the book, and so do characters with nothing in 60 days." },
		de = { "Freunde-Tagebücher: zuverlässiger", "Ein Tagebuch, das nur zum Teil angekommen ist, wird nochmal angefragt, statt als vollständig zu gelten, alles wird alle paar Minuten neu angeboten, falls ein Angebot verloren ging, und eine Anfrage eines Freundes zu beantworten lässt das Spiel nicht mehr ruckeln. Wer nicht mehr dein Battle.net-Freund ist, fällt aus dem Buch, genauso Charaktere ohne etwas in 60 Tagen." } },
	{ id = 72, module = "chronicle",
		en = { "Friends at a glance, news on its own tab", "The Friends tab shows everyone in two tables: who's online (level, where they are, what they're doing) and who isn't (when they last played, this week's time, their latest news). Hover a row for all of it, click it for their graphs. What everyone did has a tab of its own, News, which shows how much is new: no more scrolling past the list to get to it." },
		de = { "Freunde-Überblick, eigener Tab Neues","Der Freunde-Tab zeigt alle in zwei Tabellen: wer online ist (Level, wo, was er gerade macht) und wer nicht (wann zuletzt gespielt, Spielzeit diese Woche, das Neueste). Fahr über eine Zeile für alles, klick sie für ihre Graphen. Was alle gemacht haben, hat einen eigenen Tab, Neues, der zeigt, wie viel neu ist: kein Scrollen mehr an der Liste vorbei." } },
	{ id = 73, module = "chronicle",
		en = { "Compare: pick any graph, with symbols", "The big chart at the top of the Compare page isn't only level any more: icons above it switch to time played, XP, quests, kills, deaths, gold, distance, bosses and rares, time AFK or jumps, per day or adding up. Symbols on the lines show everyone's big moments: a skull where someone died, a dragon for a boss, every tenth level, dungeons, rares, epic loot and more. Hover a symbol for what happened, a day for everyone's numbers, or click any small chart to show it big." },
		de = { "Vergleich: jeder Graph, mit Symbolen", "Der große Graph oben auf der Vergleich-Seite zeigt nicht mehr nur Level: Symbole darüber wechseln zu Spielzeit, EP, Quests, Kills, Toden, Gold, Strecke, Bossen und Rares, Zeit AFK oder Sprüngen, pro Tag oder zusammengezählt. Symbole auf den Linien zeigen die großen Momente: ein Totenkopf, wo jemand gestorben ist, ein Drache für einen Boss, jedes zehnte Level, Dungeons, Rares, epische Items und mehr. Fahr über ein Symbol, um zu sehen, was passiert ist, über einen Tag für die Zahlen aller, oder klick einen kleinen Graphen an, um ihn groß zu zeigen." } },
	{ id = 74, module = "beacon",
		en = { "Beacon: fixes from a check-up", "With many WoW friends who don't run LefthyTools, the greetings to them no longer hold up your chat lines or Need answers. A friend's first message right after they come online no longer gets lost. Error reports stay saved until they've really gone out. Switching map pings off removes the markers already up, and a friend going away takes theirs along. No more death alert when a friend switches sharing on while already dead, and the enemy count is right again after switching Beacon off and on." },
		de = { "Beacon: Korrekturen nach Durchsicht", "Bei vielen WoW-Freunden ohne LefthyTools halten die Grüße an sie deine Chatzeilen und Bedarf-Antworten nicht mehr auf. Die erste Nachricht eines Freundes direkt nach dem Einloggen geht nicht mehr verloren. Fehlerberichte bleiben gespeichert, bis sie wirklich raus sind. Kartenpings ausschalten entfernt auch die Markierungen, die schon da sind, und ein Freund, der weg ist, nimmt seine mit. Kein Todesalarm mehr, wenn ein Freund das Teilen einschaltet, während er schon tot ist, und die Gegnerzahl stimmt wieder nach Beacon aus und an." } },
	{ id = 75, module = "tweaks",
		en = { "Bags and flights: small fixes", "The bags' search box no longer moves over twice when the bags open without the game placing it again (after Alt+Z, say). In gamepad mode, clicking an item in a flight's subtitles shows its tooltip without risking blocked buttons later. A flight not taken from the flight map (a quest's) no longer gets the previous flight's destination and time." },
		de = { "Taschen und Flüge: kleine Korrekturen", "Das Suchfeld der Taschen rutscht nicht mehr doppelt zur Seite, wenn die Taschen aufgehen, ohne dass das Spiel es neu setzt (etwa nach Alt+Z). Im Gamepad-Modus zeigt ein Klick auf ein Item in den Untertiteln eines Flugs seinen Tooltip, ohne dass später Buttons blockiert werden können. Ein Flug, der nicht über die Flugkarte gebucht wurde (der einer Quest), bekommt nicht mehr Ziel und Zeit des letzten Flugs." } },
	{ id = 76, module = "mirage",
		en = { "Mirage: minimap lists stay in view", "A minimap button's list, like the stream spyglass's, keeps the minimap in view while it's open, so it no longer fades away under your mouse. And pressing Toggle Minimap during a cinematic flight no longer switches the minimap off for good." },
		de = { "Mirage: Minimap-Listen bleiben sichtbar", "Die Liste eines Minimap-Buttons, etwa die vom Fernrohr für Streams, hält die Minimap sichtbar, solange sie offen ist, sie blendet also nicht mehr unter deiner Maus aus. Und Minimap umschalten während eines Flugs im Kinomodus schaltet die Minimap nicht mehr dauerhaft aus." } },
	{ id = 77, module = "tweaks",
		en = { "Combo points: dots in the health bar", "The combo point gem beside your target's level is gone. Instead, small dots sit in the middle of its health bar, one for each point you can have: lit ones in the colour of your points, the rest dark, each on a dark ring so it reads on a red bar. They take no room, so nothing else on the nameplate moves. A slider sets their size, and Try it shows them counting up on a stand-in nameplate." },
		de = { "Combopunkte: Punkte in der Leiste", "Der Combopunkt neben dem Level deines Ziels ist weg. Stattdessen sitzen kleine Punkte in der Mitte seiner Lebensleiste, einer für jeden Punkt, den du haben kannst: die aktiven in der Farbe deiner Punkte, die übrigen dunkel, jeder auf einem dunklen Ring, damit er auch auf roter Leiste gut lesbar ist. Sie brauchen keinen Platz, an der Namensplakette verschiebt sich also nichts. Ein Regler bestimmt ihre Größe, und Ausprobieren zeigt sie hochzählend an einer Beispiel-Namensplakette." } },
	{ id = 78, module = "tweaks",
		en = { "Retail unit frames, if you want them", "Forever's latest patch drew the player, target, focus, party and pet frames in a classic style. A new Misc Tweaks option, off by default, brings back retail's: their art, bars and layout (the game still has them). Switching it off takes a /reload." },
		de = { "Einheitenfenster wie in Retail", "Seit Forevers letztem Patch sind die Fenster für Spieler, Ziel, Fokus, Gruppe und Pet im Classic-Stil. Eine neue Option in Misc Tweaks, standardmäßig aus, holt die aus Retail zurück: Grafik, Leisten und Anordnung (das Spiel hat sie noch). Zum Ausschalten ist ein /reload nötig." } },
	{ id = 79, module = "beacon",
		en = { "Lefthy chat is now LTC, with /ltc", "Lefthy chat is called LTC (LefthyTools chat) now: lines show as [LTC] [Anna], the chat box says LTC:, and /ltc works like /l. Friends who haven't updated still see [Lefthy]; nothing else changes." },
		de = { "Lefthy-Chat heißt jetzt LTC, mit /ltc", "Der Lefthy-Chat heißt jetzt LTC (LefthyTools-Chat): Zeilen erscheinen als [LTC] [Anna], im Chatfeld steht LTC:, und /ltc funktioniert wie /l. Freunde ohne Update sehen weiter [Lefthy]; sonst ändert sich nichts." } },
	{ id = 80, module = "beacon",
		en = { "Fight stream: health, estimated", "A friend's stream now shows their health: a green bar over their power bar, with a percent beside it. The game hides health from addons, so it's added up from the hits and heals they take and set right whenever they're back at full health, which is why it says ~80%: about. Right after a /reload (in a fight, say) it isn't known for a while: then it says ~?, and hovering tells why. Friends need this update to send theirs." },
		de = { "Kampf-Stream: Leben, geschätzt", "Der Stream eines Freundes zeigt jetzt sein Leben: eine grüne Leiste über der Ressourcenleiste, mit Prozent daneben. Das Spiel verbirgt das Leben vor Addons, deshalb wird es aus den Treffern und Heilungen zusammengezählt und jedes Mal korrigiert, wenn er wieder volles Leben hat; daher ~80%: ungefähr. Direkt nach einem /reload (etwa im Kampf) ist es eine Weile nicht bekannt: dann steht dort ~?, und der Tooltip sagt, warum. Freunde brauchen dieses Update, um ihres zu senden." } },
	{ id = 81, module = "beacon",
		en = { "Fight stream: hits, heals, XP and loot", "What happens to a friend floats up in their stream: the hits they take in red, heals in green (bigger when big), a dodge or miss, XP rising from the mob that died, and green or better loot with its icon and name. Their kills since you opened the window count at the top right. Your own stream and the demo show it too." },
		de = { "Kampf-Stream: Treffer, Heilung, EP, Loot", "Was einem Freund passiert, steigt in seinem Stream auf: Treffer, die er abbekommt, in Rot, Heilungen in Grün (größer, wenn sie groß sind), ein Ausweichen oder Verfehlen, EP, die vom gestorbenen Mob aufsteigen, und grüner oder besserer Loot mit Symbol und Namen. Seine Kills, seit du das Fenster geöffnet hast, stehen oben rechts. Dein eigener Stream und die Demo zeigen es auch." } },
	{ id = 82, module = "beacon",
		en = { "Fight stream: casting mobs glow again", "Forever hides what a mob casts, which also hid that it was casting: the purple glow on its dot never came. The game still says when a cast begins and ends, so the glow is back, and the tooltip and bottom line say it's casting a spell (which one stays hidden)." },
		de = { "Kampf-Stream: Zaubernde Mobs leuchten", "Forever verbirgt, was ein Mob zaubert, und damit auch, dass er zaubert: das violette Leuchten an seinem Punkt kam nie. Das Spiel sagt aber noch, wann ein Zauber beginnt und endet, also ist das Leuchten zurück, und Tooltip und unterste Zeile sagen, dass er einen Zauber wirkt (welchen, bleibt verborgen)." } },
	{ id = 83, module = "beacon",
		en = { "Friends' health in tooltips and lists", "A friend's health (the same estimate as in their fight stream) now shows beside their level: on their map dot's tooltip, on the AFK screen and in a flight's bars, green, yellow below half, red below a quarter. It goes to every friend, not only to whoever watches their stream. Friends need this update to send theirs." },
		de = { "Leben der Freunde in Tooltips und Listen", "Das Leben eines Freundes (dieselbe Schätzung wie in seinem Kampf-Stream) steht jetzt neben seinem Level: im Tooltip seines Kartenpunkts, auf dem AFK-Bildschirm und in den Balken eines Flugs, grün, unter der Hälfte gelb, unter einem Viertel rot. Es geht an alle Freunde, nicht nur an die, die seinen Stream schauen. Freunde brauchen dieses Update, um ihres zu senden." } },
	{ id = 84, module = "beacon",
		en = { "Fight stream: the enemies, with health", "Under the spells, the stream now shows the enemies fighting them (up to five) and their target, the target first with a gold edge: a small still model of each whole mob and a health bar under it. In your own stream that's their real health. In a friend's it's estimated from the hits they take, against what a mob of their level usually has, and once one of their kind is seen from full health to dead, against what their kind really has (at every level). Elites and rares say ? until then. What's learned stays with your LefthyTools. A mob your game hasn't met yet shows its initials until its model has loaded." },
		de = { "Kampf-Stream: Gegner mit Leben", "Unter den Zaubern zeigt der Stream jetzt die Gegner, die mit ihm kämpfen (bis zu fünf), und sein Ziel, das Ziel zuerst mit goldenem Rand: ein kleines, stilles Modell jedes ganzen Mobs und eine Lebensleiste darunter. In deinem eigenen Stream ist das ihr echtes Leben. In dem eines Freundes wird es geschätzt: die Treffer, die sie abbekommen, gemessen an dem, was ein Mob ihres Levels üblicherweise hat, und sobald einer ihrer Art von vollem Leben bis zum Tod gesehen wurde, an dem, was ihre Art wirklich hat (auf jedem Level). Elites und Rares zeigen bis dahin ?. Was gelernt wird, bleibt in deinem LefthyTools. Ein Mob, den dein Spiel noch nicht kennt, zeigt seine Initialen, bis sein Modell geladen ist." } },
	{ id = 85, module = "chronicle",
		en = { "Compare: no friend counted twice", "Days a friend sends from a character their synced journal doesn't have yet, or from an older LefthyTools, now count for their BattleTag, so they no longer show up as a second person marked (friend)." },
		de = { "Vergleich: kein Freund mehr doppelt", "Tage, die ein Freund von einem Charakter schickt, den sein abgeglichenes Tagebuch noch nicht hat, oder von einem älteren LefthyTools, zählen jetzt für seinen BattleTag: er erscheint nicht mehr als zweite Person mit (Freund)." } },
	{ id = 86, module = "chronicle",
		en = { "Chronicle: you, not one character", "Statistics, Graphs and the Timeline now add up all your characters, and each number shows once: time AFK only in the Martin tracker, no character and all-characters versions side by side. Only levels, time per level and the session you're playing stay per character. The dropdown at the top lists each person once: you, then every friend by BattleTag with their characters. A friend's graphs add up their characters too, and time AFK is back in the graphs." },
		de = { "Chronicle: du, nicht ein Charakter", "Statistiken, Grafiken und die Zeitleiste zählen jetzt alle deine Charaktere zusammen, und jede Zahl steht nur einmal da: Zeit AFK nur im Martin-Tracker, keine Charakter- und Alle-Charaktere-Werte mehr nebeneinander. Nur Level, Zeit pro Level und die laufende Session bleiben pro Charakter. Das Dropdown oben zeigt jede Person einmal: dich, dann jeden Freund nach BattleTag mit seinen Charakteren. Die Grafiken eines Freundes zählen seine Charaktere auch zusammen, und Zeit AFK ist zurück in den Grafiken." } },
	{ id = 87, module = "chronicle",
		en = { "Friends tab: a row per friend", "Not online lists each friend once, with all their characters together (hover the row for them), and a friend who's online no longer shows up there with their other characters as well." },
		de = { "Freunde-Tab: eine Zeile pro Freund", "Nicht online zeigt jeden Freund einmal, mit allen seinen Charakteren zusammen (fahr über die Zeile für die Liste), und ein Freund, der online ist, steht dort nicht mehr zusätzlich mit seinen anderen Charakteren." } },
	{ id = 88, module = "bestiary",
		en = { "Bestiary: what mobs drop", "A new module that keeps track of what the mobs you kill drop. A minimap button opens a window that follows your target: your kills of that mob, the coin each brought, and every item it dropped with how many you got and its drop chance. Hover a drop for its tooltip, Shift-click to link it. The window stays open until you close it. Only kills you made on your own and looted count, so the chances hold. A setting shows a hovered enemy's drops next to the mouse. All your characters add to it; it stays on your computer. /bestiary log shows what was made of your last loot windows." },
		de = { "Bestiary: was Mobs droppen", "Ein neues Modul merkt sich, was die Mobs droppen, die du tötest. Ein Minimap-Button öffnet ein Fenster, das deinem Ziel folgt: deine Kills dieses Mobs, das Geld pro Kill und jedes Item, das er gedroppt hat, mit wie vielen du bekommen hast und der Dropchance. Fahr über einen Drop für seinen Tooltip, Shift-Klick verlinkt ihn. Das Fenster bleibt offen, bis du es schließt. Es zählen nur Kills, die du allein gemacht und gelootet hast, damit die Chancen stimmen. Eine Einstellung zeigt die Drops eines Gegners neben der Maus, wenn du über ihn fährst. Alle deine Charaktere tragen dazu bei; es bleibt auf deinem Computer. /bestiary log zeigt, was aus deinen letzten Loot-Fenstern wurde." } },
	{ id = 89, module = "bestiary",
		en = { "Bestiary: skinning", "What you skin is kept too, apart from the drops: per kind of mob, how often you skinned it and what came, with the chance per skinning. Skinning's pelt icon marks it in the window, the ledger and item tooltips. The window also shows the coin each kill brought on average, or no coin." },
		de = { "Bestiary: Kürschnern", "Was du kürschnerst, wird auch festgehalten, getrennt von den Drops: pro Art von Mob, wie oft du ihn gekürschnert hast und was dabei kam, mit der Chance pro Kürschnern. Das Fell-Symbol des Kürschnerns markiert es im Fenster, im Verzeichnis und in Item-Tooltips. Das Fenster zeigt außerdem das Geld pro Kill im Schnitt, oder kein Geld." } },
	{ id = 90, module = "bestiary",
		en = { "Bestiary: drop chances on items", "An item's tooltip, in your bags, in chat or anywhere, lists the three mobs it comes from likeliest, with the drop chance and how many kills that's from. A setting, on by default. Shift-click on the minimap button now switches the drops next to the mouse on or off." },
		de = { "Bestiary: Dropchancen an Items", "Der Tooltip eines Items, in deinen Taschen, im Chat oder sonstwo, zeigt die drei Mobs, von denen es am wahrscheinlichsten kommt, mit der Dropchance und aus wie vielen Kills. Eine Einstellung, standardmäßig an. Shift-Klick auf den Minimap-Button schaltet jetzt die Drops neben der Maus an oder aus." } },
	{ id = 91, module = "bestiary",
		en = { "Bestiary: the ledger, with search", "Every mob you've killed in one list: kills, level and its best drops at a glance, sorted as you like. Pick one for its slowly turning model, kills, coin, first and last kill and all its drops. The search finds mobs and items from a few of their letters. At the top: everything in all, the coin per kill and your rarest find. Open it with the book in the window, Ctrl-click on the minimap button or /bestiary ledger." },
		de = { "Bestiary: das Verzeichnis, mit Suche", "Jeder Mob, den du getötet hast, in einer Liste: Kills, Level und seine besten Drops auf einen Blick, sortiert wie du willst. Wähl einen für sein langsam drehendes Modell, Kills, Geld, ersten und letzten Kill und alle seine Drops. Die Suche findet Mobs und Items aus ein paar ihrer Buchstaben. Oben: alles zusammen, das Geld pro Kill und dein seltenster Fund. Öffnen mit dem Buch im Fenster, Strg-Klick auf den Minimap-Button oder /bestiary ledger." } },
	{ id = 92, module = "bestiary",
		en = { "Bestiary: world drops apart", "Random green and better gear that drops from mobs anywhere no longer sits among a mob's own drops: in the window a mob's world drops gather in one place, a map with how many, and hovering it lists them with their chances; in the ledger they're a section of their own, each with its item tooltip. Anything that has dropped from three or more kinds of mobs counts as one too. Item tooltips say when an item is a world drop." },
		de = { "Bestiary: Weltdrops getrennt", "Zufällige grüne und bessere Ausrüstung, die überall von Mobs droppt, steht nicht mehr zwischen den eigenen Drops eines Mobs: im Fenster sammeln sich die Weltdrops eines Mobs an einer Stelle, eine Karte mit ihrer Anzahl, und darüberfahren listet sie mit ihren Chancen; im Verzeichnis haben sie einen eigenen Abschnitt, jeder mit seinem Item-Tooltip. Was von drei oder mehr Arten von Mobs gedroppt ist, zählt auch dazu. Item-Tooltips sagen, wenn ein Item ein Weltdrop ist." } },
	{ id = 93, module = "bestiary",
		en = { "Bestiary: compare with a drop database", "The Bestiary can now show what a mob should drop, from a classic world database (CMaNGOS Classic DB) that comes with LefthyTools as an add-on of its own. Each of your drops shows the database's chance beside yours, or that it doesn't list it. In the ledger each row shows how much of a mob's loot you've found, and the picked mob has a section of what you haven't seen yet, faded, and the database's coin; hovering one shows how many you'd have expected by now. The window can show that section under your drops too, and the small card beside the mouse what a mob you haven't killed can drop (two settings, both off). Quest items are marked with a !. WoW: Forever may differ from classic, so your own numbers stay apart. A setting, on by default; restart the game once after this update." },
		de = { "Bestiary: Vergleich mit Drop-Datenbank", "Das Bestiary kann jetzt zeigen, was ein Mob droppen sollte, aus einer Classic-Weltdatenbank (CMaNGOS Classic DB), die als eigenes Addon mit LefthyTools kommt. Jeder deiner Drops zeigt die Chance der Datenbank neben deiner, oder dass sie ihn nicht kennt. Im Verzeichnis zeigt jede Zeile, wie viel vom Loot eines Mobs du gefunden hast, und der gewählte Mob hat einen Abschnitt mit dem, was du noch nicht gesehen hast, verblasst, und dem Geld laut Datenbank; darüberfahren zeigt, wie viele du bis jetzt erwartet hättest. Das Fenster kann diesen Abschnitt auch unter deinen Drops zeigen, und die kleine Karte neben der Maus, was ein Mob, den du noch nicht getötet hast, droppen kann (zwei Einstellungen, beide aus). Quest-Items sind mit einem ! markiert. WoW: Forever kann von Classic abweichen, deshalb bleiben deine eigenen Zahlen getrennt. Eine Einstellung, standardmäßig an; nach diesem Update einmal das Spiel neu starten." } },
	{ id = 94, module = "bestiary",
		en = { "Bestiary: mouse drops hidden in combat", "The drops next to the mouse no longer show while you're in combat, and go away when a fight starts; when it ends with the mouse still over an enemy, they come back. A setting, on by default, right under the drops next to the mouse." },
		de = { "Bestiary: Maus-Drops im Kampf versteckt", "Die Drops neben der Maus erscheinen nicht mehr, während du im Kampf bist, und verschwinden, wenn ein Kampf beginnt; endet er, während die Maus noch über einem Gegner ist, kommen sie zurück. Eine Einstellung, standardmäßig an, direkt unter den Drops neben der Maus." } },
	{ id = 95, module = "tweaks",
		en = { "Who has aggro, on enemy nameplates", "In a group, the left end of each enemy's health bar now says who it's attacking: >YOU< when it's you, else the first three letters of their name in the colour of their role: tank blue, healer green, damage red, white without a role. Small, outlined with a shadow, so the colour is what you see first. A mob casting at the healer while you tank it still says >YOU<. Roles come from the dungeon finder or a role check: in a group you made yourself, the leader can now start one (Misc Tweaks, or /lefthy tweaks rolecheck), and everyone picks in Blizzard's window. Try it (/lefthy tweaks aggrotest) shows examples on the enemy nameplates you see. Restart the game once after this update." },
		de = { "Wer Aggro hat, auf Namensplaketten", "In einer Gruppe zeigt das linke Ende des Lebensbalkens jedes Gegners jetzt, wen er angreift: >DU<, wenn du es bist, sonst die ersten drei Buchstaben des Namens in der Farbe der Rolle: Tank blau, Heiler grün, DD rot, weiß ohne Rolle. Klein, mit Umriss und Schatten, damit man zuerst die Farbe sieht. Ein Mob, der auf den Heiler zaubert, während du ihn tankst, zeigt weiter >DU<. Die Rollen kommen aus dem Dungeonbrowser oder einem Rollencheck: in einer selbst erstellten Gruppe kann der Anführer jetzt einen starten (Misc Tweaks, oder /lefthy tweaks rolecheck), und jeder wählt in Blizzards Fenster. Ausprobieren (/lefthy tweaks aggrotest) zeigt Beispiele auf den feindlichen Namensplaketten, die du siehst. Nach diesem Update einmal das Spiel neu starten." } },
	{ id = 96, module = "general",
		en = { "The installer updates itself", "Update-LefthyTools.cmd now checks for a newer installer first: if there is one, it uses it and replaces itself with it, so your copy, and the one you pass on, never goes out of date. Copies from before this one can't do that yet: this is the last time you need a new file." },
		de = { "Der Installer aktualisiert sich", "Update-LefthyTools.cmd sucht jetzt zuerst nach einem neueren Installer: gibt es einen, nimmt es diesen und ersetzt sich selbst damit, sodass deine Kopie, und die, die du weitergibst, nie veraltet. Kopien von vorher können das noch nicht: dies ist das letzte Mal, dass du eine neue Datei brauchst." } },
	{ id = 97, module = "beacon",
		en = { "Fight stream: the battle row", "Under a stream's map the row of mobs is now a little battle, Pokémon style: on the left the one you watch, on the right the mobs they fight. They cast their spells at their target or step up and strike it; the mob flinches and roughly what it lost floats up from it. Mobs lunge at them; their hits, heals, dodges and loot float up from their model, and the dead fall. It's an approximation from what the game tells addons. A friend near you in your group looks like themselves; one elsewhere is their race wearing their gear, glowing in their class colour. Druids show the form they're in, weapons are sheathed while casting, skinning kneels, and a mob that dies falls at once. Restart the game once after this update." },
		de = { "Kampf-Stream: die Kampfreihe", "Unter der Karte eines Streams ist die Reihe der Mobs jetzt ein kleiner Kampf, im Pokémon-Stil: links der, den du zuschaust, rechts die Mobs, gegen die er kämpft. Er zaubert auf sein Ziel oder tritt vor und schlägt zu; der Mob zuckt zusammen, und ungefähr was er verloren hat, steigt von ihm auf. Mobs stürzen sich auf ihn; seine Treffer, Heilungen, Ausweichen und Loot steigen von seinem Modell auf, und die Toten fallen. Es ist eine Annäherung aus dem, was das Spiel Addons verrät. Ein Freund in deiner Nähe in deiner Gruppe sieht aus wie er selbst; einer woanders ist seine Rasse in seiner Ausrüstung, leuchtend in seiner Klassenfarbe. Druiden zeigen ihre Gestalt, beim Zaubern ist die Waffe weggesteckt, beim Kürschnern wird gekniet, und ein Mob, der stirbt, fällt sofort. Nach diesem Update einmal das Spiel neu starten." } },
	-- New entries go here, at the end.
}
